@dataclass
class Event:
    name: str
    actor: str
    target: str | None = None
    amount: int = 0
    detail: str = ""
    seq: int = 0

    def __post_init__(self):
        if self.seq == 0:
            self.seq = 0  # Will be set by World.emit()

def emit(self, event: Event):
    event.seq = len(self.events) + 1
    self.events.append(event)
